<template><ul class="engine-list"><li v-for="model in models.slice(0,8)" :key="model.id"><i :class="model.status"></i><span>{{ model.label }}</span><strong :class="model.status">{{ statusLabel(model.status) }}</strong><small>{{ model.model }}</small></li></ul></template>
<script setup lang="ts">type Engine={id:string;label:string;model:string;status:string}; defineProps<{models:Engine[]}>(); const statusLabel=(s:string)=>({enabled:'运行',configured:'就绪',standby:'待机',degraded:'异常',unconfigured:'未配置'} as Record<string,string>)[s]||s</script>
<style scoped>.engine-list{display:grid;grid-template-columns:1fr 1fr;flex:1;gap:2px 14px;margin:0;padding:6px 13px;list-style:none}.engine-list li{display:grid;grid-template-columns:7px 1fr auto;align-content:center;column-gap:7px;min-width:0;border-bottom:1px solid var(--screen-line-soft)}.engine-list i{width:6px;height:6px;margin-top:4px;border-radius:50%;background:var(--screen-text-faint)}.engine-list i.enabled,.engine-list i.configured{background:var(--screen-mint);box-shadow:0 0 10px var(--screen-mint)}.engine-list i.standby{background:var(--risk-medium)}.engine-list i.degraded{background:var(--risk-critical)}.engine-list span{overflow:hidden;color:var(--screen-text-secondary);font-size:var(--fs-screen-label);text-overflow:ellipsis;white-space:nowrap}.engine-list strong{color:var(--screen-text-muted);font-size:var(--fs-screen-code)}.engine-list strong.enabled,.engine-list strong.configured{color:var(--screen-mint)}.engine-list strong.degraded{color:var(--risk-critical)}.engine-list small{grid-column:2/4;overflow:hidden;color:var(--screen-text-faint);font:var(--fs-screen-code) var(--font-code);text-overflow:ellipsis;white-space:nowrap}@media(max-width:1199px){.engine-list{gap:2px 8px;padding-inline:9px}}</style>
